        _updateBriefing(state, preserveResults) {
            var period = Math.min((state.currentPeriod || 1), 3);
            var idx = period - 1;

            var roundKeys = [
                { titleKey: 'round1_title', descKey: 'round1_desc', panel: 'round1Panel' },
                { titleKey: 'round2_title', descKey: 'round2_desc', panel: 'round2Panel' },
                { titleKey: 'round3_title', descKey: 'round3_desc', panel: 'round3Panel' }
            ];

            if (idx >= roundKeys.length) return;

            var round = roundKeys[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl && window.mySimulation) {
                titleEl.innerHTML = window.mySimulation.t(round.titleKey);
            }

            var textEl = document.getElementById('briefingText');
            if (textEl && window.mySimulation) {
                textEl.innerHTML = window.mySimulation.t(round.descKey);
            }

            for (var i = 0; i < roundKeys.length; i++) {
                var panel = document.getElementById(roundKeys[i].panel);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }

            var ds = state.domainState || {};
            var events = ds.events || {};
            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');

            if (eventPanel && eventText && window.mySimulation) {
                var eventHtml = '';

                if (period === 1) {
                    if (events.roommateLeaves) {
                        eventHtml += window.mySimulation.t('event_roommate') + '<br>';
                    }
                    if (events.performanceBonus) {
                        eventHtml += window.mySimulation.t('event_bonus') + '<br>';
                    }
                }
                if (period === 2) {
                    if (events.flashSale) {
                        eventHtml += window.mySimulation.t('event_flash_sale') + '<br>';
                    }
                }
                if (period === 3) {
                    if (events.familyBorrow) {
                        eventHtml += window.mySimulation.t('event_family_borrow') + '<br>';
                    }
                }

                if (eventHtml) {
                    eventText.innerHTML = eventHtml;
                    eventPanel.style.display = 'block';
                } else {
                    eventPanel.style.display = 'none';
                }
            }

            if (!preserveResults) {
                var resultsPanel = document.getElementById('resultsPanel');
                if (resultsPanel) resultsPanel.style.display = 'none';
            }
            // Projection + completion are only relevant on the terminal round, which is never
            // auto-advanced away from, so always clear them when (re)briefing an active round.
            var projPanel = document.getElementById('projectionPanel');
            if (projPanel) projPanel.style.display = 'none';
            var cmPanel = document.getElementById('mpsCompletionPanel');
            if (cmPanel) { cmPanel.style.display = 'none'; cmPanel.innerHTML = ''; }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new MiPrimerSueldoAdapter(), {
            simulationType: 'mi_primer_sueldo',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

